// Some portions generated by Claude
// @ts-check
const { test, expect } = require('@playwright/test');
const {
    deleteRepository,
    memoryRepositoryConfiguration,
    repositoryPageUrl,
    serverBaseUrl,
    uniqueRepositoryId,
    waitForRoute
} = require('./workbench-test-helpers.js');

// The Map view places resources that have geo:lat and geo:long (or schema:latitude and schema:longitude) and frames
// all of them.
const REPOSITORY_ID = uniqueRepositoryId('graph-map');
const DATA = `
@prefix ex: <http://example.org/map/> .
@prefix geo: <http://www.w3.org/2003/01/geo/wgs84_pos#> .
@prefix schema: <http://schema.org/> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
ex:oslo rdfs:label "Oslo" ; geo:lat 59.91 ; geo:long 10.75 ; ex:near ex:bergen .
ex:bergen rdfs:label "Bergen" ; schema:geo [ schema:latitude 60.39 ; schema:longitude 5.32 ] .
`;

test.beforeAll(async ({ request }) => {
    const repositoryUrl = `${serverBaseUrl()}/repositories/${REPOSITORY_ID}`;
    const created = await request.put(repositoryUrl, {
        headers: { 'Content-Type': 'text/turtle' },
        data: memoryRepositoryConfiguration(REPOSITORY_ID, 'Graph map')
    });
    expect([200, 201, 204]).toContain(created.status());
    const loaded = await request.post(`${repositoryUrl}/statements`, {
        headers: { 'Content-Type': 'text/turtle' },
        data: DATA
    });
    expect([200, 204]).toContain(loaded.status());
});

test.afterAll(async ({ request }) => {
    await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

test('the Map view places resources by geo:lat/geo:long and schema:geo coordinates', async ({ page }) => {
    await page.route('https://www.openstreetmap.org/**', (route) => route.fulfill({ status: 200, body: '<html></html>' }));
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto(repositoryPageUrl(REPOSITORY_ID, 'graph'));
    await waitForRoute(page, 'graph');
    const explorer = page.locator('.graph-explorer');
    await explorer.getByRole('button', { name: 'Load 100 statements' }).click();
    await expect(explorer.locator('.recommended-mark')).toHaveCount(0);
    await explorer.locator('.view-menu > summary').click();
    await expect(explorer.locator('.view-menu-popover button', { hasText: 'Map' })).toContainText('Recommended');
    await explorer.locator('.view-menu-popover button', { hasText: 'Map' }).click();

    const places = explorer.locator('.map-locations button');
    await expect(places).toHaveCount(2);
    await expect(places.nth(0)).toContainText('Oslo');
    await expect(places.nth(0)).toContainText('59.9100, 10.7500');
    await expect(places.nth(1)).toContainText('Bergen');
    await expect(places.nth(1)).toContainText('60.3900, 5.3200');
    await expect(explorer.locator('.map-shell iframe')).toHaveAttribute('src', /bbox=4\.777%2C59\.862%2C11\.293%2C60\.438/);
});
